import { SectionTabs } from '@/lib/designsystem';

const sections = [
  { id: 'profile', title: 'Profile' },
  { id: 'settings', title: 'Settings' },
];

export default function MyComponent() {
  return (
    <SectionTabs
      sections={sections}
      initialSectionId="profile"
      contentPadding="sm"
    >
      {(activeSectionId) => (
        <div>
          {activeSectionId === 'profile' && <div>Profile Content</div>}
          {activeSectionId === 'settings' && <div>Settings Content</div>}
        </div>
      )}
    </SectionTabs>
  );
}

import { SectionTabs } from '@/lib/designsystem';
import { useState } from 'react';

const sections = [
  { id: 'preview', title: 'Preview' },
  { id: 'creator', title: 'Creator' },
];

export default function MyPage() {
  const [activeTab, setActiveTab] = useState('preview');

  return (
    <>
      <SectionTabs
        sections={sections}
        activeTabId={activeTab}
        onTabChange={setActiveTab}
      />
      {/* Render content externally based on activeTab state */}
      {/* Note: contentPadding prop has no effect in controlled mode */}
      <div>
        {activeTab === 'preview' && <div>Preview Content Area</div>}
        {activeTab === 'creator' && <div>Creator Content Area</div>}
      </div>
    </>
  );
}

import { SectionTabs } from '@/lib/designsystem';
import { Home, Settings, Bell } from 'lucide-react';

const sections = [
